    SELECT AVG(height_cm) AS average_height
    FROM (
        SELECT height_cm
        FROM (
            SELECT s.id, s.height_cm
            FROM superhero AS s
            INNER JOIN publisher AS p ON s.publisher_id = p.id
            WHERE p.publisher_name = 'Marvel Comics'
        ) AS c_cols
    ) AS c_rows
)
SELECT * FROM t_agg;

